import './App.css';
import {BrowserRouter as Router, Route, Routes} from "react-router-dom";
import Login from './pages/login/login';
import Chat from './pages/chat/chat';

function App() {
  return (
   <Router>
    <Routes>
    <Route path="/" component={Login} />
    <Route path="/chat" component={Chat} />

    </Routes>

   </Router>
  );
}

export default App;
